import os
import re
from flask import Response, request, Flask

app = Flask(__name__)


@app.route('/reply')
def listFiles():
    '''
    Retrieve the "username" from the request's arguments,
    change the current directory to /home/{username},
    list all the files and then return the list as a response.
    '''
    username = request.args.get('username', '')

    # Validate username to prevent path traversal and injection.
    # Allow only typical safe username characters.
    if not username or not re.fullmatch(r'[A-Za-z0-9_-]+', username):
        return Response('Invalid username', status=400)

    base_dir = '/home'
    # Build the target path safely and ensure it stays within /home.
    target_dir = os.path.normpath(os.path.join(base_dir, username))
    if os.path.commonpath([base_dir, target_dir]) != base_dir:
        return Response('Invalid username', status=400)

    if not os.path.isdir(target_dir):
        return Response('Directory not found', status=404)

    try:
        files = os.listdir(target_dir)
    except OSError:
        return Response('Unable to list files', status=500)

    return Response('\n'.join(files), mimetype='text/plain')

