import ast
import operator


def evalInput(inputStr):
    '''
    Safely evaluate inputStr as a Python arithmetic expression and return the result.

    Only supports literal numbers and basic arithmetic operators
    (+, -, *, /, //, %, **, unary +/-). Any attempt to call functions,
    access names/attributes, or use other constructs raises ValueError.
    '''
    # Allowed binary operators
    _bin_ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
    }

    # Allowed unary operators
    _unary_ops = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        # Numeric literals only
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float, complex)) and not isinstance(node.value, bool):
                return node.value
            raise ValueError("Only numeric literals are allowed")
        if isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in _bin_ops:
                raise ValueError(f"Operator not allowed: {op_type.__name__}")
            # Guard against extremely large exponentiation (resource exhaustion)
            if isinstance(node.op, ast.Pow):
                left = _eval(node.left)
                right = _eval(node.right)
                if isinstance(right, (int, float)) and right > 1000:
                    raise ValueError("Exponent too large")
                return _bin_ops[op_type](left, right)
            return _bin_ops[op_type](_eval(node.left), _eval(node.right))
        if isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in _unary_ops:
                raise ValueError(f"Unary operator not allowed: {op_type.__name__}")
            return _unary_ops[op_type](_eval(node.operand))
        raise ValueError(f"Disallowed expression element: {type(node).__name__}")

    if not isinstance(inputStr, str):
        raise TypeError("inputStr must be a string")

    try:
        parsed = ast.parse(inputStr, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"Invalid expression: {exc}") from exc

    return _eval(parsed)

def parse(data):
    if data is None:
        return None
    return data.split(',')


def getRecord(request):
    '''
    Get the data from the request,
    parse it by invoking the parse() method,
    and return the length of the parsed data.
    '''
    data = request.get('data') if isinstance(request, dict) else getattr(request, 'data', None)
    parsed = parse(data)
    if parsed is None:
        return 0
    return len(parsed)

import os, signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    # Validate that processID is an integer (or convertible to one)
    try:
        pid = int(processID)
    except (TypeError, ValueError):
        raise ValueError("processID must be a valid integer")

    # Reject non-positive PIDs to avoid signaling process groups (0),
    # every process (-1), or invalid targets.
    if pid <= 0:
        raise ValueError("processID must be a positive integer")

    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        # No such process; nothing to kill.
        pass
    except PermissionError:
        # Not permitted to signal this process.
        raise

