app = Flask(__name__)

# Allow-list of safe operators for arithmetic evaluation only.
_ALLOWED_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_ALLOWED_UNARYOPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def _safe_eval(node):
    '''Recursively evaluate a restricted arithmetic AST node.'''
    if isinstance(node, ast.Expression):
        return _safe_eval(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)):
            return node.value
        raise ValueError("Only numeric constants are allowed.")
    if isinstance(node, ast.BinOp) and type(node.op) in _ALLOWED_BINOPS:
        left = _safe_eval(node.left)
        right = _safe_eval(node.right)
        # Guard against resource-exhaustion via huge exponents.
        if isinstance(node.op, ast.Pow) and (abs(right) > 100 or abs(left) > 10_000):
            raise ValueError("Exponent operands too large.")
        return _ALLOWED_BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in _ALLOWED_UNARYOPS:
        return _ALLOWED_UNARYOPS[type(node.op)](_safe_eval(node.operand))
    raise ValueError("Unsupported or disallowed expression.")


@app.route("/evalcode")
def eval_code():
    '''
    Safely evaluate a simple arithmetic expression supplied by the user.

    NOTE: This intentionally does NOT execute arbitrary Python code, which
    would be a remote-code-execution vulnerability. Only basic math on
    numeric literals is permitted.
    '''
    expr = request.args.get("expr", "")
    if len(expr) > 200:
        return "Expression too long.", 400
    try:
        tree = ast.parse(expr, mode="eval")
        result = _safe_eval(tree)
    except (ValueError, SyntaxError, TypeError, ZeroDivisionError, OverflowError):
        return "Invalid or disallowed expression.", 400
    return str(result), 200

