import hmac


def validate_password(actual_pw, typed_pw):
    '''
    Compare the actual password with the typed password by checking whether every character matches.
    '''
    if actual_pw is None or typed_pw is None:
        return False

    # Encode strings to bytes for a consistent, constant-time comparison.
    if isinstance(actual_pw, str):
        actual_bytes = actual_pw.encode('utf-8')
    else:
        actual_bytes = actual_pw

    if isinstance(typed_pw, str):
        typed_bytes = typed_pw.encode('utf-8')
    else:
        typed_bytes = typed_pw

    # hmac.compare_digest performs a constant-time comparison,
    # mitigating timing attacks that could leak information about the password.
    return hmac.compare_digest(actual_bytes, typed_bytes)

import pickle
import json


class Payload(object):
    def __reduce__(self):
        return exec, ('import os;os.system("ls")',)


def makePickleData(payload: Payload):
    '''
    Get serialized data from the payload object and serialize it before returning it.

    NOTE: This intentionally does NOT use pickle to serialize arbitrary objects,
    because pickle can execute arbitrary code during (de)serialization
    (see the Payload.__reduce__ exploit above). Instead, only explicitly
    allow-listed, safe attributes are extracted and serialized as JSON.
    '''
    if not isinstance(payload, Payload):
        raise TypeError("Expected a Payload instance")

    # Extract only simple, safe attributes rather than serializing the object
    # itself (which would carry the dangerous __reduce__ behavior).
    allowed_types = (str, int, float, bool, type(None))
    safe_data = {
        key: value
        for key, value in vars(payload).items()
        if not key.startswith("_") and isinstance(value, allowed_types)
    }

    # JSON serialization cannot execute code, unlike pickle.
    return json.dumps(safe_data).encode("utf-8")

from flask import request, send_file, Flask, abort
from pathlib import Path

app = Flask(__name__)
app.config.setdefault("DOWNLOAD_FOLDER", str(Path(app.root_path) / "downloads"))

@app.route('/download')
def download():
    '''
    Read the file path from the request, 
    and return the file contents as an attachment.
    '''
    requested_path = request.args.get("path") or request.args.get("file")
    if not requested_path or "\x00" in requested_path:
        abort(400)

    base_dir = Path(app.config["DOWNLOAD_FOLDER"]).resolve()
    file_path = (base_dir / requested_path).resolve()

    try:
        file_path.relative_to(base_dir)
    except ValueError:
        abort(403)

    if not file_path.is_file():
        abort(404)

    return send_file(file_path, as_attachment=True, download_name=file_path.name)

