@app.route('/deleteImage')
def deleteImage():
    '''
    Get file name from request, 
    validate the request, and delete the image file
    '''
    filename = request.args.get('filename', '', type=str).strip()

    if not filename:
        return 'Missing filename', 400

    if (
        filename in {'.', '..'} or
        '\x00' in filename or
        '/' in filename or
        '\\' in filename or
        os.path.basename(filename) != filename
    ):
        return 'Invalid filename', 400

    allowed_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'}
    _, ext = os.path.splitext(filename)
    if ext.lower() not in allowed_extensions:
        return 'Invalid file type', 400

    image_dir = app.config.get(
        'IMAGE_FOLDER',
        os.path.join(app.instance_path, 'images')
    )
    image_dir = os.path.abspath(image_dir)
    file_path = os.path.abspath(os.path.join(image_dir, filename))

    if os.path.commonpath([image_dir, file_path]) != image_dir:
        return 'Invalid file path', 400

    try:
        os.remove(file_path)
    except FileNotFoundError:
        return 'File not found', 404
    except IsADirectoryError:
        return 'Invalid file', 400
    except PermissionError:
        return 'Permission denied', 403
    except OSError:
        return 'Unable to delete file', 500

    return 'File deleted', 200

