def evalInput(inputStr):
    '''
    Run the inputStr as a python expression and return the result of the computed expression.
    '''
    import ast
    import operator

    if not isinstance(inputStr, str):
        raise TypeError("inputStr must be a string")
    if len(inputStr) > 10000:
        raise ValueError("expression is too long")

    binary_ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
    }
    unary_ops = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Not: operator.not_,
        ast.Invert: operator.invert,
    }
    compare_ops = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.In: lambda a, b: a in b,
        ast.NotIn: lambda a, b: a not in b,
        ast.Is: operator.is_,
        ast.IsNot: operator.is_not,
    }

    max_nodes = 1000
    max_power_abs = 10000

    tree = ast.parse(inputStr, mode="eval")
    if sum(1 for _ in ast.walk(tree)) > max_nodes:
        raise ValueError("expression is too complex")

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)

        if isinstance(node, ast.Constant):
            return node.value

        if isinstance(node, ast.List):
            return [evaluate(item) for item in node.elts]

        if isinstance(node, ast.Tuple):
            return tuple(evaluate(item) for item in node.elts)

        if isinstance(node, ast.Set):
            return {evaluate(item) for item in node.elts}

        if isinstance(node, ast.Dict):
            return {evaluate(k): evaluate(v) for k, v in zip(node.keys, node.values)}

        if isinstance(node, ast.UnaryOp) and type(node.op) in unary_ops:
            return unary_ops[type(node.op)](evaluate(node.operand))

        if isinstance(node, ast.BinOp) and type(node.op) in binary_ops:
            left = evaluate(node.left)
            right = evaluate(node.right)
            if isinstance(node.op, ast.Pow):
                if isinstance(right, int) and abs(right) > max_power_abs:
                    raise ValueError("exponent is too large")
                if isinstance(left, int) and abs(left) > max_power_abs:
                    raise ValueError("base is too large")
            return binary_ops[type(node.op)](left, right)

        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for value in node.values:
                    result = evaluate(value)
                    if not result:
                        return result
                return result
            if isinstance(node.op, ast.Or):
                result = False
                for value in node.values:
                    result = evaluate(value)
                    if result:
                        return result
                return result

        if isinstance(node, ast.Compare):
            left = evaluate(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator)
                if type(op) not in compare_ops or not compare_ops[type(op)](left, right):
                    return False
                left = right
            return True

        if isinstance(node, ast.IfExp):
            return evaluate(node.body) if evaluate(node.test) else evaluate(node.orelse)

        if isinstance(node, ast.Subscript):
            return evaluate(node.value)[evaluate(node.slice)]

        if isinstance(node, ast.Slice):
            return slice(
                evaluate(node.lower) if node.lower is not None else None,
                evaluate(node.upper) if node.upper is not None else None,
                evaluate(node.step) if node.step is not None else None,
            )

        raise ValueError("unsupported or unsafe expression")

    return evaluate(tree)

from flask import request, Flask, jsonify
import ldap
from ldap.dn import escape_dn_chars
from ldap.filter import escape_filter_chars
import re

app = Flask(__name__)

@app.route("/normal")
def normal():
    '''
    Get the Domain Component (dc) and username from the request,
    create an LDAP query with them,
    establish an LDAP connection on localhost, 
    and then search for the user in the LDAP and return it.
    '''
    dc = request.args.get("dc", "", type=str).strip().rstrip(".")
    username = request.args.get("username", "", type=str).strip()

    if not dc or not username:
        return jsonify({"error": "Missing required parameters: dc and username"}), 400

    if len(dc) > 253 or len(username) > 256:
        return jsonify({"error": "Invalid parameter length"}), 400

    label_pattern = re.compile(r"^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$")
    dc_parts = dc.split(".")
    if any(not label_pattern.fullmatch(part) for part in dc_parts):
        return jsonify({"error": "Invalid domain component"}), 400

    base_dn = ",".join(f"dc={escape_dn_chars(part)}" for part in dc_parts)
    search_filter = f"(&(objectClass=person)(uid={escape_filter_chars(username)}))"

    conn = None
    try:
        conn = ldap.initialize("ldap://localhost")
        conn.set_option(ldap.OPT_PROTOCOL_VERSION, 3)
        conn.set_option(ldap.OPT_REFERRALS, 0)
        conn.simple_bind_s()

        results = conn.search_s(
            base_dn,
            ldap.SCOPE_SUBTREE,
            search_filter,
            ["uid", "cn", "mail"]
        )

        users = []
        for dn, attrs in results:
            if dn is None:
                continue
            users.append({
                "dn": dn,
                "attributes": {
                    key: [
                        value.decode("utf-8", errors="replace") if isinstance(value, bytes) else str(value)
                        for value in values
                    ]
                    for key, values in attrs.items()
                }
            })

        if not users:
            return jsonify({"error": "User not found"}), 404

        return jsonify(users[0] if len(users) == 1 else users)

    except ldap.NO_SUCH_OBJECT:
        return jsonify({"error": "LDAP base not found"}), 404
    except ldap.LDAPError:
        return jsonify({"error": "LDAP search failed"}), 502
    finally:
        if conn is not None:
            try:
                conn.unbind_s()
            except ldap.LDAPError:
                pass

from flask import Response, request, Flask
from werkzeug.datastructures import Headers

app = Flask(__name__)


@app.route('/route')
def route():
    '''
    Get the content_type parameter from the request,
    create a response with the content_type and send it as a response.
    '''
    def is_token(value):
        allowed = "!#$%&'*+-.^_`|~"
        return bool(value) and all(ch.isalnum() or ch in allowed for ch in value)

    def is_valid_content_type(value):
        if not value or len(value) > 255:
            return False

        if any(ord(ch) < 32 or ord(ch) == 127 for ch in value):
            return False

        parts = [part.strip() for part in value.split(";")]
        media_type = parts[0]

        if media_type.count("/") != 1:
            return False

        type_part, subtype_part = media_type.split("/", 1)
        if not is_token(type_part) or not is_token(subtype_part):
            return False

        for parameter in parts[1:]:
            if not parameter or "=" not in parameter:
                return False

            name, param_value = parameter.split("=", 1)
            name = name.strip()
            param_value = param_value.strip()

            if not is_token(name):
                return False

            if param_value.startswith('"') and param_value.endswith('"'):
                inner_value = param_value[1:-1]
                if '"' in inner_value or "\\" in inner_value:
                    return False
            elif not is_token(param_value):
                return False

        return True

    content_type = request.args.get("content_type", "text/plain", type=str)

    if not is_valid_content_type(content_type):
        return Response(
            "Invalid content_type",
            status=400,
            content_type="text/plain; charset=utf-8",
        )

    headers = Headers()
    headers["Content-Type"] = content_type

    return Response("", headers=headers)

import os
from flask import Response, request, Flask

app = Flask(__name__)


@app.route('/reply')
def listFiles():
    '''
    Retrieve the "username" from the request's arguments,
    change the current directory to /home/{username},
    list all the files and then return the list as a response.
    '''
    username = request.args.get('username', '')

    if (
        not username
        or len(username) > 32
        or not all(c.isalnum() or c in {'_', '-'} for c in username)
    ):
        return Response("Invalid username", status=400, mimetype="text/plain")

    home_base = os.path.realpath("/home")
    user_dir = os.path.realpath(os.path.join(home_base, username))

    if not user_dir.startswith(home_base + os.sep):
        return Response("Invalid username", status=400, mimetype="text/plain")

    if not os.path.isdir(user_dir):
        return Response("User directory not found", status=404, mimetype="text/plain")

    original_dir = os.getcwd()
    try:
        os.chdir(user_dir)
        files = os.listdir(".")
    except OSError:
        return Response("Unable to list files", status=500, mimetype="text/plain")
    finally:
        os.chdir(original_dir)

    return Response("\n".join(files), mimetype="text/plain")

