    Kill the process with the given processID.
    '''
    if isinstance(processID, bool):
        raise ValueError("processID must be a positive integer")

    if isinstance(processID, int):
        pid = processID
    elif isinstance(processID, str):
        value = processID.strip()
        if not value.isdecimal():
            raise ValueError("processID must be a positive integer")
        pid = int(value, 10)
    else:
        try:
            pid = processID.__index__()
        except AttributeError:
            raise ValueError("processID must be a positive integer") from None

    if pid <= 0:
        raise ValueError("processID must be a positive integer")

    os.kill(pid, signal.SIGTERM)

