from Crypto.Cipher import *


def send_encrypted(secret_key, channel, message):
    '''
    Encrypt the message after creating a cipher,
    and send it over the channel passed as parameter.
    '''
    from Crypto.Cipher import AES
    from Crypto.Random import get_random_bytes

    if not isinstance(secret_key, (bytes, bytearray, memoryview)):
        raise TypeError("secret_key must be bytes-like")
    key = bytes(secret_key)
    if len(key) not in (16, 24, 32):
        raise ValueError("secret_key must be 16, 24, or 32 bytes long")

    if isinstance(message, str):
        plaintext = message.encode("utf-8")
    elif isinstance(message, (bytes, bytearray, memoryview)):
        plaintext = bytes(message)
    else:
        raise TypeError("message must be str or bytes-like")

    nonce = get_random_bytes(12)
    cipher = AES.new(key, AES.MODE_GCM, nonce=nonce)
    ciphertext, tag = cipher.encrypt_and_digest(plaintext)
    payload = nonce + tag + ciphertext

    if hasattr(channel, "sendall"):
        return channel.sendall(payload)

    if hasattr(channel, "send"):
        sent = channel.send(payload)
        if isinstance(sent, int):
            total_sent = sent
            view = memoryview(payload)
            while total_sent < len(payload):
                chunk_sent = channel.send(view[total_sent:])
                if not isinstance(chunk_sent, int):
                    break
                if chunk_sent == 0:
                    raise ConnectionError("channel connection broken")
                total_sent += chunk_sent
        return sent

    if hasattr(channel, "write"):
        return channel.write(payload)

    raise TypeError("channel must provide sendall, send, or write")

