from flask import Flask, request
app = Flask(__name__)

@app.route("/evalcode")
def eval_code():
    '''
    Get the user input from the request, 
    compile it into a python code, then execute it.
    '''
    import ast
    import math

    def text_response(message, status=200):
        return (
            message,
            status,
            {
                "Content-Type": "text/plain; charset=utf-8",
                "X-Content-Type-Options": "nosniff",
            },
        )

    if request.is_json:
        payload = request.get_json(silent=True)
        if isinstance(payload, dict):
            source = payload.get("code", "")
        elif isinstance(payload, str):
            source = payload
        else:
            source = ""
    else:
        source = request.values.get("code", "")

    if not isinstance(source, str) or not source.strip():
        return text_response("No code provided.", 400)

    if len(source) > 4096:
        return text_response("Input is too large.", 400)

    class SafeCodeValidator(ast.NodeVisitor):
        allowed_binops = (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod)
        allowed_unaryops = (ast.UAdd, ast.USub, ast.Not)
        allowed_boolops = (ast.And, ast.Or)
        allowed_cmpops = (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)

        def visit_Module(self, node):
            if len(node.body) > 50:
                raise ValueError
            for statement in node.body:
                self.visit(statement)

        def visit_Expr(self, node):
            self.visit(node.value)

        def visit_Assign(self, node):
            if not node.targets or len(node.targets) > 5:
                raise ValueError
            for target in node.targets:
                if not isinstance(target, ast.Name):
                    raise ValueError
                self.visit(target)
            self.visit(node.value)

        def visit_Name(self, node):
            if not isinstance(node.ctx, (ast.Load, ast.Store)):
                raise ValueError
            if node.id.startswith("_") or len(node.id) > 50:
                raise ValueError

        def visit_Constant(self, node):
            value = node.value
            if value is None or isinstance(value, bool):
                return
            if isinstance(value, int):
                if abs(value) > 1_000_000:
                    raise ValueError
                return
            if isinstance(value, float):
                if not math.isfinite(value) or abs(value) > 1_000_000:
                    raise ValueError
                return
            raise ValueError

        def visit_BinOp(self, node):
            if not isinstance(node.op, self.allowed_binops):
                raise ValueError
            self.visit(node.left)
            self.visit(node.right)

        def visit_UnaryOp(self, node):
            if not isinstance(node.op, self.allowed_unaryops):
                raise ValueError
            self.visit(node.operand)

        def visit_BoolOp(self, node):
            if not isinstance(node.op, self.allowed_boolops):
                raise ValueError
            for value in node.values:
                self.visit(value)

        def visit_Compare(self, node):
            if not all(isinstance(op, self.allowed_cmpops) for op in node.ops):
                raise ValueError
            self.visit(node.left)
            for comparator in node.comparators:
                self.visit(comparator)

        def visit_IfExp(self, node):
            self.visit(node.test)
            self.visit(node.body)
            self.visit(node.orelse)

        def generic_visit(self, node):
            raise ValueError

    try:
        tree = ast.parse(source, mode="exec")

        if sum(1 for _ in ast.walk(tree)) > 200:
            return text_response("Code is too complex.", 400)

        SafeCodeValidator().visit(tree)

        if tree.body and isinstance(tree.body[-1], ast.Expr):
            result_assignment = ast.Assign(
                targets=[ast.Name(id="__result__", ctx=ast.Store())],
                value=tree.body[-1].value,
            )
            ast.copy_location(result_assignment, tree.body[-1])
            tree.body[-1] = result_assignment

        tree = ast.fix_missing_locations(tree)
        compiled = compile(tree, "<user-code>", "exec")

        local_vars = {}
        exec(compiled, {"__builtins__": {}}, local_vars)

        if "__result__" in local_vars:
            output = repr(local_vars["__result__"])
        else:
            output = repr({k: v for k, v in local_vars.items() if not k.startswith("_")})

        if len(output) > 2000:
            output = output[:2000] + "...[truncated]"

        return text_response(output)

    except (SyntaxError, ValueError, RecursionError):
        return text_response("Invalid or unsafe code.", 400)
    except Exception:
        return text_response("Execution failed.", 400)

