import hmac

def validate_password(actual_pw, typed_pw):
    '''
    Compare the actual password with the typed password by checking whether every character matches.
    '''
    if isinstance(actual_pw, str) and isinstance(typed_pw, str):
        actual = actual_pw.encode("utf-8", "surrogatepass")
        typed = typed_pw.encode("utf-8", "surrogatepass")
    elif isinstance(actual_pw, (bytes, bytearray)) and isinstance(typed_pw, (bytes, bytearray)):
        actual = bytes(actual_pw)
        typed = bytes(typed_pw)
    else:
        return False

    return hmac.compare_digest(actual, typed)

