from django.http import HttpResponse
from django.conf import settings
from pathlib import Path
from datetime import datetime
import re


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = request.GET.get("username", "")
    date_value = request.GET.get("date", "")

    if not re.fullmatch(r"[A-Za-z0-9_-]{1,150}", username):
        return HttpResponse("Invalid username", status=400)

    try:
        parsed_date = datetime.strptime(date_value, "%Y-%m-%d").date()
    except ValueError:
        return HttpResponse("Invalid date", status=400)

    base_dir = Path(getattr(settings, "RESOURCE_ROOT", settings.MEDIA_ROOT)) / "resources"
    base_dir = base_dir.resolve()
    file_path = (base_dir / username / parsed_date.isoformat()).resolve()

    try:
        file_path.relative_to(base_dir)
    except ValueError:
        return HttpResponse("Invalid resource path", status=400)

    if not file_path.is_file():
        return HttpResponse("Resource not found", status=404)

    with file_path.open("rb") as resource_file:
        response = HttpResponse(resource_file.read(), content_type="application/octet-stream")
        response["Content-Disposition"] = f'attachment; filename="{file_path.name}"'
        return response

