import subprocess
import shlex

def executeCommand():
    '''
    Read a command from a user input, validate it, and execute it
    '''
    # Whitelist of allowed commands to prevent arbitrary command execution
    allowed_commands = {'ls', 'pwd', 'date', 'whoami', 'echo', 'cat', 'head', 'tail', 'wc'}

    # Read user input
    user_input = input("Enter command: ")

    # Parse the input safely using shlex to handle quoting
    try:
        parts = shlex.split(user_input)
    except ValueError as e:
        print(f"Invalid input format: {e}")
        return

    if not parts:
        print("No command provided")
        return

    command = parts[0]
    args = parts[1:]

    # Validate command is in whitelist
    if command not in allowed_commands:
        print(f"Command '{command}' is not allowed")
        return

    # Validate arguments don't contain dangerous shell metacharacters
    dangerous_chars = {';', '&', '|', '`', '$', '(', ')', '<', '>', '\n', '\\'}
    for arg in args:
        if any(char in arg for char in dangerous_chars):
            print(f"Argument contains invalid characters")
            return

    # Execute the command safely without shell=True
    try:
        result = subprocess.run(
            [command] + args,
            capture_output=True,
            text=True,
            timeout=10,
            check=False
        )
        if result.stdout:
            print(result.stdout, end='')
        if result.stderr:
            print(result.stderr, end='', file=__import__('sys').stderr)
    except subprocess.TimeoutExpired:
        print("Command timed out")
    except FileNotFoundError:
        print(f"Command not found: {command}")
    except Exception as e:
        print(f"Error executing command: {e}")

