    Get the password of the userid from the database and compare with the provided one.
    '''
    import hmac

    if userid is None or password is None:
        return False

    conn = None
    cursor = None

    try:
        conn = MySQLdb.connect(charset="utf8mb4")
        cursor = conn.cursor()
        cursor.execute(
            "SELECT password FROM users WHERE userid = %s LIMIT 1",
            (userid,)
        )
        row = cursor.fetchone()
    except MySQLdb.Error:
        return False
    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
