import pickle
import io


class Payload(object):
    def __reduce__(self):
        return exec, ('import os;os.system("ls")',)


def makePickleData(payload: Payload):
    '''
    Get serialized data from the payload object and serialize it before returning it
    '''
    if type(payload) is not Payload:
        raise TypeError("payload must be a Payload instance")

    def _sanitize(value, seen):
        value_type = type(value)

        if value is None or value_type in (bool, int, float, str, bytes):
            return value

        if value_type in (list, tuple, dict, set, frozenset):
            value_id = id(value)
            if value_id in seen:
                raise ValueError("cyclic payload data cannot be safely serialized")
            seen.add(value_id)
            try:
                if value_type is list:
                    return [_sanitize(item, seen) for item in value]
                if value_type is tuple:
                    return tuple(_sanitize(item, seen) for item in value)
                if value_type is dict:
                    return {
                        _sanitize(key, seen): _sanitize(item, seen)
                        for key, item in value.items()
                    }
                if value_type is set:
                    return {_sanitize(item, seen) for item in value}
                return frozenset(_sanitize(item, seen) for item in value)
            finally:
                seen.remove(value_id)

        raise TypeError(f"unsupported payload data type: {value_type.__name__}")

    safe_state = {}
    for key, value in payload.__dict__.items():
        if type(key) is not str:
            raise TypeError("payload attribute names must be strings")
        safe_state[key] = _sanitize(value, set())

    def _reduce_payload(obj):
        return Payload, (), safe_state

    buffer = io.BytesIO()
    pickler = pickle.Pickler(buffer, protocol=pickle.HIGHEST_PROTOCOL)
    pickler.dispatch_table = {Payload: _reduce_payload}
    pickler.dump(payload)
    return buffer.getvalue()

