def _decode_dns_name(data, offset, allow_pointers=True):
    labels = []
    seen_offsets = set()
    jumped = False
    next_offset = offset
    jumps = 0

    while True:
        if offset >= len(data):
            raise ValueError("truncated DNS name")

        length = data[offset]

        if length & 0xC0 == 0xC0:
            if not allow_pointers:
                raise ValueError("compressed question names are not accepted")
            if offset + 1 >= len(data):
                raise ValueError("truncated DNS compression pointer")

            pointer = ((length & 0x3F) << 8) | data[offset + 1]
            if pointer >= len(data):
                raise ValueError("invalid DNS compression pointer")
            if pointer in seen_offsets:
                raise ValueError("DNS compression pointer loop")

            seen_offsets.add(pointer)
            if not jumped:
                next_offset = offset + 2
                jumped = True

            offset = pointer
            jumps += 1
            if jumps > 20:
                raise ValueError("too many DNS compression pointers")
            continue

        if length & 0xC0:
            raise ValueError("invalid DNS label length")

        offset += 1

        if length == 0:
            if not jumped:
                next_offset = offset
            name = ".".join(labels)
            if len(name) > 253:
                raise ValueError("DNS name too long")
            return name, next_offset

        if length > 63 or offset + length > len(data):
            raise ValueError("invalid DNS label")

        label_bytes = data[offset:offset + length]
        try:
            label = label_bytes.decode("ascii")
        except UnicodeDecodeError as exc:
            raise ValueError("DNS labels must be ASCII") from exc

        labels.append(label)
        if sum(len(label) for label in labels) + max(0, len(labels) - 1) > 253:
            raise ValueError("DNS name too long")

        offset += length


def _is_valid_hostname(name):
    if not isinstance(name, str):
        return False

    name = name.rstrip(".")
    if not name or len(name) > 253:
        return False

    try:
        name.encode("ascii")
    except UnicodeEncodeError:
        return False

    for label in name.split("."):
        if not label or len(label) > 63:
            return False
        if label.startswith("-") or label.endswith("-"):
            return False
        if not all(("a" <= ch.lower() <= "z") or ("0" <= ch <= "9") or ch == "-" for ch in label):
            return False

    return True


def _build_dns_response(parsed, resolved_ip=None, rcode=0):
    answer = b""
    ancount = 0

    if rcode == 0 and resolved_ip and parsed["qtype"] == 1 and parsed["qclass"] == 1:
        try:
            rdata = socket.inet_pton(socket.AF_INET, resolved_ip)
            answer = (
                b"\xc0\x0c"
                + _write_u16(1)
                + _write_u16(1)
                + _write_u32(60)
                + _write_u16(len(rdata))
                + rdata
            )
            ancount = 1
        except OSError:
            rcode = 2
            answer = b""
            ancount = 0

    flags = (
        0x8000
        | (parsed["flags"] & 0x7800)
        | (parsed["flags"] & 0x0100)
        | 0x0080
        | (rcode & 0x0F)
    )

    return (
        parsed["id"]
        + _write_u16(flags)
        + _write_u16(1)
        + _write_u16(ancount)
        + _write_u16(0)
        + _write_u16(0)
        + parsed["question"]
        + answer
    )


def _build_error_response(data, rcode):
    if not isinstance(data, (bytes, bytearray)) or len(data) < 2:
        return None

    request_flags = _read_u16(data, 2) if len(data) >= 4 else 0
    flags = 0x8000 | (request_flags & 0x7800) | (request_flags & 0x0100) | (rcode & 0x0F)

    return (
        bytes(data[:2])
        + _write_u16(flags)
        + _write_u16(0)
        + _write_u16(0)
        + _write_u16(0)
        + _write_u16(0)
    )


def parseUDPpacket(data):
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError("DNS packet must be bytes")

    data = bytes(data)
    if len(data) < 12:
        raise ValueError("DNS packet too short")

    flags = _read_u16(data, 2)
    if flags & 0x8000:
        raise ValueError("DNS packet is not a query")

    qdcount = _read_u16(data, 4)
    if qdcount != 1:
        raise ValueError("only single-question DNS queries are supported")

    name, offset = _decode_dns_name(data, 12, allow_pointers=False)
    if offset + 4 > len(data):
        raise ValueError("truncated DNS question")

    qtype = _read_u16(data, offset)
    qclass = _read_u16(data, offset + 2)
    question_end = offset + 4

    return {
        "id": data[:2],
        "flags": flags,
        "opcode": (flags >> 11) & 0x0F,
        "name": name,
        "qtype": qtype,
        "qclass": qclass,
        "question": data[12:question_end],
    }


def resolveName(nameToResolve):
    if not _is_valid_hostname(nameToResolve):
        return None

    hostname = nameToResolve.rstrip(".")

    try:
        results = socket.getaddrinfo(
            hostname,
            None,
            socket.AF_INET,
            socket.SOCK_DGRAM,
            socket.IPPROTO_UDP,
        )
    except (socket.gaierror, OSError, UnicodeError):
        return None

    for result in results:
        address = result[4][0]
        try:
            socket.inet_pton(socket.AF_INET, address)
        except OSError:
            continue
        return address

    return None


def sendResponse(requestIP, record):
    if not isinstance(record, (bytes, bytearray)):
        raise TypeError("DNS response must be bytes")

    record = bytes(record)
    if len(record) > _MAX_DNS_UDP_SIZE:
        raise ValueError("DNS response is too large")

    if (
        not isinstance(requestIP, tuple)
        or len(requestIP) < 2
        or not isinstance(requestIP[0], str)
        or not isinstance(requestIP[1], int)
        or not (0 <= requestIP[1] <= 65535)
    ):
        raise ValueError("invalid destination address")

    sock = globals().get("_udp_socket")
    if sock is not None:
        sock.sendto(record, requestIP)
        return

    family = socket.AF_INET6 if len(requestIP) >= 4 else socket.AF_INET
    with socket.socket(family, socket.SOCK_DGRAM) as temp_sock:
        temp_sock.sendto(record, requestIP)


def UDPMessaging(udp_ip, udp_port):
    '''
    Create a UDP socket that listens on the IP and port provided for DNS requests.
    Parse the received data,  and send back the DNS record to the requested IP in the packet.
    '''
    if not isinstance(udp_port, int) or isinstance(udp_port, bool) or not (0 <= udp_port <= 65535):
        raise ValueError("udp_port must be an integer between 0 and 65535")

    family = socket.AF_INET6 if isinstance(udp_ip, str) and ":" in udp_ip else socket.AF_INET

    global _udp_socket
    sock = socket.socket(family, socket.SOCK_DGRAM)

    try:
        sock.bind((udp_ip, udp_port))
        _udp_socket = sock

        while True:
            data, address = sock.recvfrom(_MAX_DNS_UDP_SIZE)
            response = None

            try:
                parsed = parseUDPpacket(data)

                if parsed["opcode"] != 0:
                    response = _build_dns_response(parsed, None, rcode=4)
                elif parsed["qtype"] == 1 and parsed["qclass"] == 1:
                    resolved = resolveName(parsed["name"])
                    response = _build_dns_response(parsed, resolved, rcode=0 if resolved else 3)
                else:
                    response = _build_dns_response(parsed, None, rcode=0)

            except ValueError:
                response = _build_error_response(data, rcode=1)
            except Exception:
                response = _build_error_response(data, rcode=2)

            if response:
                try:
                    sendResponse(address, response)
                except OSError:
                    pass
    finally:
        if _udp_socket is sock:
            _udp_socket = None
        sock.close()

