import subprocess
import shlex
import sys

def executeCommand():
    '''
    Read a command from a user input, validate it, and execute it
    '''
    # Whitelist of allowed commands (no arguments are validated beyond this)
    ALLOWED_COMMANDS = {'ls', 'pwd', 'date', 'whoami', 'echo'}

    user_input = input("Enter command: ").strip()
    if not user_input:
        print("No command entered.")
        return

    # Safely parse the command into a list of arguments
    try:
        args = shlex.split(user_input)
    except ValueError as e:
        print(f"Invalid command syntax: {e}")
        return

    if not args:
        print("No command parsed.")
        return

    command = args[0]
    if command not in ALLOWED_COMMANDS:
        print(f"Command '{command}' is not allowed.")
        return

    # Execute the command safely (no shell, list of arguments)
    try:
        result = subprocess.run(args, capture_output=True, text=True, check=False)
        if result.stdout:
            print(result.stdout, end='')
        if result.stderr:
            print(result.stderr, end='', file=sys.stderr)
    except Exception as e:
        print(f"Error executing command: {e}", file=sys.stderr)

