from flask import Response, request, Flask

app = Flask(__name__)


@app.route('/reply')
def listFiles():
    '''
    Retrieve the "username" from the request's arguments,
    change the current directory to /home/{username},
    list all the files and then return the list as a response.
    '''
    username = request.args.get('username')
    if not username:
        return Response("Missing 'username' parameter", status=400)

    # Validate username to prevent directory traversal
    if not re.match(r'^[a-zA-Z0-9_-]+$', username):
        return Response("Invalid username", status=400)

    # Build the target directory path
    user_dir = os.path.join('/home', username)

    # Resolve the real path to prevent symlink attacks
    real_dir = os.path.realpath(user_dir)
    if not real_dir.startswith('/home/'):
        return Response("Access denied", status=403)

    try:
        # List files directly instead of changing the global working directory
        files = os.listdir(real_dir)
    except FileNotFoundError:
        return Response("User directory not found", status=404)
    except NotADirectoryError:
        return Response("Not a directory", status=400)
    except PermissionError:
        return Response("Permission denied", status=403)

    # Return the list as a plain text response, one file per line
    return Response('\n'.join(files), mimetype='text/plain')

