import os
from django.http import HttpResponse, HttpResponseBadRequest, HttpResponseNotFound


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = request.GET.get('username')
    date = request.GET.get('date')
    if not username or not date:
        return HttpResponseBadRequest("Missing username or date")

    # Sanitize inputs to prevent path traversal
    # Allow only alphanumeric, underscore, and hyphen for username
    if not username.replace('_', '').replace('-', '').isalnum():
        return HttpResponseBadRequest("Invalid username")
    # Allow only digits and hyphens for date (expected format: YYYY-MM-DD)
    if not all(c.isdigit() or c == '-' for c in date):
        return HttpResponseBadRequest("Invalid date")

    # Base directory where resource files are stored
    BASE_DIR = '/var/data/resources'  # Should be configured securely
    # Safely construct the file path
    file_path = os.path.normpath(os.path.join(BASE_DIR, username, date))
    # Ensure the resolved path is still within BASE_DIR
    if not file_path.startswith(os.path.normpath(BASE_DIR)):
        return HttpResponseBadRequest("Invalid path")

    # Check if the file exists and is a regular file
    if not os.path.isfile(file_path):
        return HttpResponseNotFound("File not found")

    try:
        with open(file_path, 'rb') as f:
            content = f.read()
    except IOError:
        return HttpResponseNotFound("File not found")

    response = HttpResponse(content, content_type='application/octet-stream')
    response['Content-Disposition'] = f'attachment; filename="{os.path.basename(file_path)}"'
    return response

