import ast

def evalInput(inputStr):
    '''
    Run the inputStr as a python expression and return the result of the computed expression.
    '''
    try:
        tree = ast.parse(inputStr, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression: {e}")

    allowed = {
        'Expression', 'BinOp', 'UnaryOp', 'BoolOp', 'Compare', 'IfExp',
        'List', 'Tuple', 'Dict', 'Set', 'Constant', 'Num', 'Str', 'Bytes',
        'NameConstant', 'Ellipsis', 'Load',
        'Add', 'Sub', 'Mult', 'Div', 'FloorDiv', 'Mod', 'Pow',
        'LShift', 'RShift', 'BitOr', 'BitXor', 'BitAnd',
        'UAdd', 'USub', 'Not', 'Invert', 'And', 'Or',
        'Eq', 'NotEq', 'Lt', 'LtE', 'Gt', 'GtE', 'Is', 'IsNot', 'In', 'NotIn',
    }

    for node in ast.walk(tree):
        if type(node).__name__ not in allowed:
            raise ValueError(f"Disallowed expression element: {type(node).__name__}")

    code = compile(tree, '<string>', 'eval')
    return eval(code, {"__builtins__": {}}, {})

