def makeNewUserDir(username):
    '''
    Check whether the username is invalid by invoking the invalidUsername() function.
    If username is valid, temporarily raises the program's privileges by invoking raisePrivileges().
    Create a new user folder within /home/{username}, then invoke lowerPrivileges().
    Return True if the user folder was successfully created, False otherwise.
    '''
    if not isinstance(username, str) or '\0' in username or invalidUsername(username):
        return False

    base_dir = os.path.abspath("/home")
    target_dir = os.path.abspath(os.path.join(base_dir, username))

    if target_dir == base_dir:
        return False

    try:
        if os.path.commonpath([base_dir, target_dir]) != base_dir:
            return False
    except ValueError:
        return False

    try:
        raisePrivileges()
        os.mkdir(target_dir)
        return True
    except OSError:
        return False
    finally:
        lowerPrivileges()

