import sys

def executeCommand():
    '''
    Read a command from a user input, validate it, and execute it
    '''
    raw = input("Enter command: ").strip()
    if not raw:
        print("No command entered.")
        return

    try:
        args = shlex.split(raw)
    except ValueError as e:
        print(f"Invalid command syntax: {e}")
        return

    # Define a whitelist of allowed commands (base executable only)
    allowed_commands = {"ls", "pwd", "date", "whoami", "echo"}

    if args[0] not in allowed_commands:
        print(f"Command '{args[0]}' is not allowed.")
        return

    try:
        result = subprocess.run(
            args,
            capture_output=True,
            text=True,
            check=False
        )
        # Print stdout
        if result.stdout:
            print(result.stdout, end='')

        # Print stderr to the error stream
        if result.stderr:
            print(result.stderr, file=sys.stderr)
    except Exception as e:
        print(f"Error executing command: {e}")

