app = Flask(__name__)

@app.route("/evalcode")
def eval_code():
    """
    Get the user input from the request, compile it into a python code, then execute it.
    This implementation safely evaluates only pure Python expressions without side‑effects.
    """
    code = request.args.get("code")
    if code is None:
        return jsonify(error="Missing 'code' query parameter"), 400

    # Parse the code as an expression; reject anything else.
    try:
        expr_ast = ast.parse(code, mode="eval")
    except SyntaxError:
        return jsonify(error="Only valid Python expressions are allowed"), 400

    # Disallow potentially unsafe nodes.
    unsafe_nodes = (
        ast.Call, ast.Attribute, ast.Subscript,
        ast.Import, ast.ImportFrom, ast.Global, ast.Nonlocal,
        ast.Lambda, ast.Yield, ast.YieldFrom, ast.Await,
        ast.Delete, ast.Assign, ast.AugAssign, ast.Raise,
        ast.Try, ast.With, ast.AsyncWith, ast.AsyncFor,
    )
    for node in ast.walk(expr_ast):
        if isinstance(node, unsafe_nodes):
            return jsonify(error="Disallowed operation in expression"), 400

    # Evaluate in a restricted environment.
    try:
        result = eval(
            compile(expr_ast, filename="<user>", mode="eval"),
            {"__builtins__": {}},
            {}
        )
    except Exception as exc:
        return jsonify(error=f"Error during evaluation: {exc}"), 400

    return jsonify(result=result)

import ast
import operator
import math

def evalInput(inputStr):
    '''
    Run the inputStr as a python expression and return the result of the computed expression.
    '''
    # Whitelisted names (constants)
    _CONST_MAP = {
        'pi': math.pi,
        'e': math.e,
        'tau': math.tau,
        'inf': math.inf,
        'nan': math.nan,
        'True': True,
        'False': False,
        'None': None,
    }

    # Whitelisted functions
    _FUNC_MAP = {
        'abs': abs,
        'round': round,
        'len': len,
        'sum': sum,
        'min': min,
        'max': max,
        'pow': pow,
        # math module functions
        'sin': math.sin,
        'cos': math.cos,
        'tan': math.tan,
        'asin': math.asin,
        'acos': math.acos,
        'atan': math.atan,
        'atan2': math.atan2,
        'sqrt': math.sqrt,
        'log': math.log,
        'log10': math.log10,
        'exp': math.exp,
        'ceil': math.ceil,
        'floor': math.floor,
        'factorial': math.factorial,
        'degrees': math.degrees,
        'radians': math.radians,
        'hypot': math.hypot,
    }

    # Mapping of AST operator nodes to actual functions
    _BIN_OPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.MatMult: operator.matmul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.LShift: operator.lshift,
        ast.RShift: operator.rshift,
        ast.BitOr: operator.or_,
        ast.BitXor: operator.xor,
        ast.BitAnd: operator.and_,
    }

    _UNARY_OPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Invert: operator.invert,
        ast.Not: operator.not_,
    }

    _BOOL_OPS = {
        ast.And: all,
        ast.Or: any,
    }

    _COMPARE_OPS = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Is: operator.is_,
        ast.IsNot: operator.is_not,
        ast.In: lambda a, b: a in b,
        ast.NotIn: lambda a, b: a not in b,
    }

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)

        # Literals
        if isinstance(node, ast.Constant):  # Python 3.8+
            return node.value
        if isinstance(node, ast.Num):  # legacy
            return node.n
        if isinstance(node, ast.Str):
            return node.s
        if isinstance(node, ast.Bytes):
            return node.s
        if isinstance(node, ast.NameConstant):
            return node.value
        if isinstance(node, ast.Ellipsis):
            return ...

        # Names (constants)
        if isinstance(node, ast.Name):
            if node.id in _CONST_MAP:
                return _CONST_MAP[node.id]
            raise ValueError(f"Use of name '{node.id}' is not allowed")

        # Binary operations
        if isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type in _BIN_OPS:
                return _BIN_OPS[op_type](left, right)
            raise ValueError(f"Binary operator {op_type} is not allowed")

        # Unary operations
        if isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            op_type = type(node.op)
            if op_type in _UNARY_OPS:
                return _UNARY_OPS[op_type](operand)
            raise ValueError(f"Unary operator {op_type} is not allowed")

        # Boolean operations
        if isinstance(node, ast.BoolOp):
            values = [_eval(v) for v in node.values]
            op_type = type(node.op)
            if op_type in _BOOL_OPS:
                # For 'and' we need all(values), for 'or' any(values)
                return _BOOL_OPS[op_type](values)
            raise ValueError(f"Boolean operator {op_type} is not allowed")

        # Comparisons
        if isinstance(node, ast.Compare):
            left = _eval(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = _eval(comparator)
                op_type = type(op)
                if op_type in _COMPARE_OPS:
                    if not _COMPARE_OPS[op_type](left, right):
                        return False
                    left = right
                else:
                    raise ValueError(f"Comparison operator {op_type} is not allowed")
            return True

        # Conditional expression (a if cond else b)
        if isinstance(node, ast.IfExp):
            test = _eval(node.test)
            return _eval(node.body) if test else _eval(node.orelse)

        # Function calls
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                func_name = node.func.id
                if func_name in _FUNC_MAP:
                    func = _FUNC_MAP[func_name]
                else:
                    raise ValueError(f"Function '{func_name}' is not allowed")
            else:
                raise ValueError("Only direct function names are allowed")
            args = [_eval(arg) for arg in node.args]
            if node.keywords:
                raise ValueError("Keyword arguments are not allowed")
            return func(*args)

        # Subscript (e.g., list[0]) - allow only for literals like tuples/lists/dicts
        if isinstance(node, ast.Subscript):
            value = _eval(node.value)
            slice_node = node.slice
            if isinstance(slice_node, ast.Slice):
                lower = _eval(slice_node.lower) if slice_node.lower else None
                upper = _eval(slice_node.upper) if slice_node.upper else None
                step = _eval(slice_node.step) if slice_node.step else None
                return value[lower:upper:step]
            else:
                index = _eval(slice_node)
                return value[index]

        # Tuple, List, Dict literals
        if isinstance(node, ast.Tuple):
            return tuple(_eval(elt) for elt in node.elts)
        if isinstance(node, ast.List):
            return [_eval(elt) for elt in node.elts]
        if isinstance(node, ast.Dict):
            return {_eval(k): _eval(v) for k, v in zip(node.keys, node.values)}

        raise ValueError(f"Unsupported syntax: {type(node).__name__}")

    # Parse the expression safely
    try:
        parsed = ast.parse(inputStr, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression: {e}") from None

    # Ensure the AST contains only allowed nodes (no imports, attribute access, etc.)
    for node in ast.walk(parsed):
        if isinstance(node, (ast.Import, ast.ImportFrom, ast.Attribute, ast.Lambda,
                             ast.FunctionDef, ast.ClassDef, ast.Assign, ast.AugAssign,
                             ast.Delete, ast.Raise, ast.Try, ast.With, ast.Yield,
                             ast.YieldFrom, ast.Global, ast.Nonlocal, ast.Call)):
            # ast.Call is allowed only when validated later; we keep it here for walk check
            if isinstance(node, ast.Call):
                continue
            raise ValueError(f"Disallowed syntax: {type(node).__name__}")

    return _eval(parsed)

import os
import re
from flask import Response, request, Flask, jsonify

app = Flask(__name__)

@app.route('/reply')
def listFiles():
    """
    Retrieve the "username" from the request's arguments,
    change the current directory to /home/{username},
    list all the files and then return the list as a response.
    """
    username = request.args.get('username', '').strip()
    if not username:
        return Response('Missing username', status=400)

    # Allow only safe characters in the username
    if not re.fullmatch(r'[\w-]+', username):
        return Response('Invalid username', status=400)

    base_dir = '/home'
    user_dir = os.path.abspath(os.path.join(base_dir, username))

    # Ensure the resolved path is still under /home
    if not user_dir.startswith(os.path.abspath(base_dir) + os.sep):
        return Response('Invalid path', status=400)

    if not os.path.isdir(user_dir):
        return Response('User directory not found', status=404)

    try:
        old_cwd = os.getcwd()
        try:
            os.chdir(user_dir)
            files = os.listdir('.')
        finally:
            os.chdir(old_cwd)
    except OSError:
        return Response('Error accessing directory', status=500)

    return jsonify(files=files)

