import os
import re
from django.conf import settings
from django.http import HttpResponse, FileResponse
from django.utils.http import urlquote


def getResource(request):
    """
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    """
    # Extract parameters (allow both GET and POST)
    username = request.GET.get('username') or request.POST.get('username')
    date_str = request.GET.get('date') or request.POST.get('date')

    # Basic validation
    if not username or not date_str:
        return HttpResponse('Missing username or date.', status=400)

    # Allow only safe characters: letters, numbers, underscore, hyphen
    if not re.fullmatch(r'[\w-]+', username):
        return HttpResponse('Invalid username.', status=400)

    # Expect ISO date format YYYY-MM-DD
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_str):
        return HttpResponse('Invalid date format. Expected YYYY-MM-DD.', status=400)

    # Build a safe absolute path inside a predefined directory
    base_dir = os.path.join(settings.BASE_DIR, 'resources')
    # Ensure the base directory exists
    if not os.path.isdir(base_dir):
        return HttpResponse('Resource directory not configured.', status=500)

    # Construct the file path safely
    filename = f"{username}_{date_str}.pdf"  # example file type
    safe_path = os.path.normpath(os.path.join(base_dir, filename))

    # Prevent path traversal: the resolved path must start with base_dir
    if not safe_path.startswith(os.path.abspath(base_dir) + os.sep):
        return HttpResponse('Invalid file path.', status=400)

    # Check file existence
    if not os.path.isfile(safe_path):
        return HttpResponse('Requested file not found.', status=404)

    # Serve the file using FileResponse for efficient streaming
    try:
        file_handle = open(safe_path, 'rb')
        response = FileResponse(file_handle, as_attachment=True, filename=urlquote(filename))
        response['Content-Type'] = 'application/pdf'
        return response
    except Exception:
        return HttpResponse('Error serving the file.', status=500)

