        # In a multi-threaded Flask environment, this would create a critical race condition.
        files = os.listdir(target_dir)
        return Response("\n".join(files))
    except (FileNotFoundError, PermissionError, NotADirectoryError):
        return Response("User directory not found or access denied", status=404)

