import socket

def parseUDPpacket(data):
    """
    Parses the raw UDP data to extract the requested hostname.
    """
    try:
        # Decode bytes to string and strip whitespace/null bytes
        return data.decode('utf-8', errors='replace').strip()
    except Exception:
        return ""


def resolveName(nameToResolve):
    """
    Resolves a hostname to its corresponding DNS record from a mock database.
    """
    # Mock DNS record database
    dns_records = {
        "localhost": "127.0.0.1",
        "example.com": "93.184.216.34",
        "google.com": "142.250.190.46",
        "python.org": "151.101.129.175"
    }
    return dns_records.get(nameToResolve, "Record not found")


def sendResponse(requestIP, record):
    """
    Sends the resolved DNS record back to the requester.
    requestIP is expected to be a tuple of (ip, port).
    """
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.sendto(record.encode('utf-8'), requestIP)
    except Exception:
        # In a production environment, log the error
        pass


def UDPMessaging(udp_ip, udp_port):
    '''
    Create a UDP socket that listens on the IP and port provided for DNS requests.
    Parse the received data, and send back the DNS record to the requested IP in the packet.
    '''
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.bind((udp_ip, udp_port))
            while True:
                try:
                    # Limit buffer size to prevent memory exhaustion (DoS)
                    data, addr = s.recvfrom(4096)

                    # Parse the hostname from the packet
                    name = parseUDPpacket(data)

                    if name:
                        # Resolve the hostname to a record
                        record = resolveName(name)
                        # Send the response back to the client address
                        sendResponse(addr, record)
                except Exception:
                    # Continue listening even if a specific packet processing fails
                    continue
    except Exception:
        # Handle socket binding errors (e.g., port already in use)
        pass

