import ast

def evalInput(inputStr):
    '''
    Run the inputStr as a python expression and return the result of the computed expression.
    '''
    allowed_nodes = {
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Constant,
        ast.Num,
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
        ast.USub, ast.UAdd,
        ast.Compare,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.BoolOp, ast.And, ast.Or,
        ast.Not,
        ast.Load,
    }
    tree = ast.parse(inputStr, mode='eval')
    for node in ast.walk(tree):
        if type(node) not in allowed_nodes:
            raise ValueError("Disallowed expression")
        if isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float, complex, type(None))):
                raise ValueError("Disallowed constant")
        if isinstance(node, ast.Num):
            if not isinstance(node.n, (int, float, complex, type(None))):
                raise ValueError("Disallowed constant")
    return eval(compile(tree, '<string>', 'eval'), {"__builtins__": None}, {})

