    elif hasattr(request, 'get_data'):
        data = request.get_data()
    elif isinstance(request, (str, bytes)):
        data = request
    else:
        data = None

    # Decode bytes to string if necessary
    if isinstance(data, bytes):
        try:
            data = data.decode('utf-8')
        except UnicodeDecodeError:
            data = None

    parsed = parse(data)
    if parsed is None:
        return 0
    return len(parsed)

