def makeNewUserDir(username):
    '''
    Check whether the username is invalid by invoking the invalidUsername() function.
    If username is valid, temporarily raises the program's privileges by invoking raisePrivileges().
    Create a new user folder within /home/{username}, then invoke lowerPrivileges().
    Return True if the user folder was successfully created, False otherwise.
    '''
    if invalidUsername(username):
        return False

    # Prevent path traversal attacks
    if not username or username != os.path.basename(username) or '..' in username:
        return False

    home_base = "/home"
    user_path = os.path.join(home_base, username)

    # Ensure the resolved path stays within /home
    try:
        user_path = os.path.normpath(user_path)
        if not user_path.startswith(os.path.normpath(home_base) + os.sep) and user_path != os.path.normpath(home_base):
            return False
    except Exception:
        return False

    raisePrivileges()
    try:
        os.makedirs(user_path, exist_ok=False)
        return True
    except (OSError, PermissionError):
        return False
    finally:
        lowerPrivileges()

