import os, signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    if not isinstance(processID, int):
        raise TypeError("processID must be an integer")
    if processID <= 0:
        raise ValueError("processID must be a positive integer")

    try:
        os.kill(processID, signal.SIGTERM)
    except ProcessLookupError:
        raise ProcessLookupError(f"No process found with PID {processID}")
    except PermissionError:
        raise PermissionError(f"Permission denied to kill process {processID}")
    except OSError as e:
        raise OSError(f"Failed to kill process {processID}: {e}")

import os


def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.
    '''
    # Resolve to absolute path and normalize
    base_dir = os.path.abspath(os.getcwd())
    requested_path = os.path.abspath(os.path.join(base_dir, fileName))

    # Prevent path traversal attacks
    if not requested_path.startswith(base_dir):
        raise ValueError("Invalid file path: path traversal attempt detected")

    # Check if file exists and is a regular file
    if not os.path.isfile(requested_path):
        raise FileNotFoundError(f"File not found: {fileName}")

    # Optional: limit file size to prevent memory exhaustion (e.g., 10MB)
    max_size = 10 * 1024 * 1024
    file_size = os.path.getsize(requested_path)
    if file_size > max_size:
        raise ValueError(f"File too large: {file_size} bytes (max {max_size})")

    # Read file safely with context manager
    try:
        with open(requested_path, 'r', encoding='utf-8') as f:
            return f.read()
    except UnicodeDecodeError:
        # Fallback for binary files or different encodings
        with open(requested_path, 'rb') as f:
            return f.read()
    except OSError as e:
        raise IOError(f"Error reading file: {e}")

