from django.http import HttpResponse, Http404, FileResponse
from django.conf import settings
import os
import re
from datetime import datetime


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = request.GET.get('username')
    date_str = request.GET.get('date')

    if not username or not date_str:
        return HttpResponse("Missing username or date parameter", status=400)

    # Validate username: alphanumeric, underscore, hyphen only, no path traversal
    if not re.match(r'^[a-zA-Z0-9_-]+$', username):
        return HttpResponse("Invalid username format", status=400)

    # Validate date format YYYY-MM-DD
    try:
        date_obj = datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        return HttpResponse("Invalid date format. Use YYYY-MM-DD", status=400)

    # Construct safe path
    base_dir = getattr(settings, 'USER_FILES_DIR', os.path.join(settings.BASE_DIR, 'user_files'))
    user_dir = os.path.join(base_dir, username)
    date_dir = os.path.join(user_dir, date_str)

    # Ensure the resolved path is within the base directory (prevent path traversal)
    try:
        base_dir = os.path.realpath(base_dir)
        requested_path = os.path.realpath(date_dir)
        if not requested_path.startswith(base_dir):
            return HttpResponse("Access denied", status=403)
    except Exception:
        return HttpResponse("Invalid path", status=400)

    # Check if directory exists
    if not os.path.isdir(requested_path):
        raise Http404("Resource not found")

    # For demonstration, serve the first file in the directory
    # In practice, you might want to serve a specific file or list files
    try:
        files = os.listdir(requested_path)
        if not files:
            raise Http404("No files found for this date")

        # Serve the first file (or implement logic to select specific file)
        file_name = files[0]
        file_path = os.path.join(requested_path, file_name)

        if not os.path.isfile(file_path):
            raise Http404("File not found")

        response = FileResponse(open(file_path, 'rb'), as_attachment=True, filename=file_name)
        return response

    except Http404:
        raise
    except Exception:
        return HttpResponse("Internal server error", status=500)

import os

def foo():
    return "./", "file.txt"


def dataSorting():
    '''
    Continuously take (basename,data) key-value pair from foo() function and sort it
    '''
    raw = foo()
    if isinstance(raw, tuple) and len(raw) == 2:
        pairs = [raw]
    else:
        pairs = raw
    result = []
    for basename, data in pairs:
        if not isinstance(basename, str) or basename in ("", ".", "..") or "/" in basename or "\\" in basename:
            continue
        result.append((basename, data))
    result.sort(key=lambda item: item[0])
    return result

