import socket

def parseUDPpacket(data):
    if not isinstance(data, bytes):
        return None
    # Limit size to avoid excessive processing
    if len(data) > 1024:
        data = data[:1024]
    # Try to parse as a basic DNS query packet
    try:
        if len(data) >= 12:
            qdcount = int.from_bytes(data[4:6], 'big')
            if qdcount > 0:
                offset = 12
                labels = []
                for _ in range(20):
                    if offset >= len(data):
                        break
                    length = data[offset]
                    if length == 0:
                        offset += 1
                        name = '.'.join(labels)
                        if name and all(c in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.-" for c in name):
                            return name
                        return None
                    if length > 63:
                        # Pointer or invalid; fall back to text parsing
                        break
                    offset += 1
                    if offset + length > len(data):
                        break
                    label = data[offset:offset+length].decode('ascii', errors='replace')
                    labels.append(label)
                    offset += length
    except Exception:
        pass
    # Fallback: treat payload as a UTF-8 string containing the domain name
    try:
        text = data.decode('utf-8', errors='replace').strip()
        if text:
            name = text.split()[0]
            if name and all(c in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.-" for c in name) and len(name) <= 253:
                return name
    except Exception:
        pass
    return None


def resolveName(nameToResolve):
    if not isinstance(nameToResolve, str) or not nameToResolve:
        return "0.0.0.0"
    if len(nameToResolve) > 253:
        return "0.0.0.0"
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.-")
    if not all(ch in allowed for ch in nameToResolve):
        return "0.0.0.0"
    try:
        return socket.gethostbyname(nameToResolve)
    except Exception:
        return "0.0.0.0"


def sendResponse(requestIP, record):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            message = str(record).encode('utf-8', errors='replace')
            if isinstance(requestIP, tuple) and len(requestIP) == 2:
                sock.sendto(message, requestIP)
            elif isinstance(requestIP, str):
                sock.sendto(message, (requestIP, 53))
    except OSError:
        pass


def UDPMessaging(udp_ip, udp_port):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            sock.bind((udp_ip, udp_port))
            while True:
                try:
                    data, addr = sock.recvfrom(1024)
                    name = parseUDPpacket(data)
                    if name is not None:
                        record = resolveName(name)
                        sendResponse(addr, record)
                except Exception:
                    continue
    except Exception:
        pass
